def max_non_palindrome_substring(s):
    n = len(s)
    dp = [[False] * n for _ in range(n)]
    max_length = 0

    # Fill the table
    for length in range(1, n + 1):
        for i in range(n - length + 1):
            j = i + length - 1
            if length == 1:
                dp[i][j] = True
            elif length == 2:
                dp[i][j] = s[i] == s[j]
            else:
                dp[i][j] = s[i] == s[j] and dp[i + 1][j - 1]

            if dp[i][j]:
                continue

            max_length = max(max_length, length)

    return max_length

